-- ▲▲▲ FIN DE LOS DATOS ▲▲▲

IF NOT EXISTS (SELECT 1 FROM #aloha_inv) AND NOT EXISTS (SELECT 1 FROM #aloha_gnd)
    THROW 50042, 'No hay datos del CSV: pegar los INSERT en B.1.', 1;

CREATE CLUSTERED INDEX IX_inv ON #aloha_inv (tienda);
CREATE CLUSTERED INDEX IX_gnd ON #aloha_gnd (tienda);

-- ─── B.2 Tiendas del ranking (las de KIO que muestra la pantalla) ───────────────────
DROP TABLE IF EXISTS #tiendas;
CREATE TABLE #tiendas (id INT IDENTITY(1, 1) PRIMARY KEY, tienda INT NOT NULL, codigo_neg INT NOT NULL);

INSERT INTO #tiendas (tienda, codigo_neg)
SELECT TRY_CONVERT(INT, t.tie_codigo_aloha), t.tie_codigo_neg
FROM [10.138.58.142].[sm_pos].[dbo].[aloha_tie_tienda] t WITH (NOLOCK)
WHERE t.tie_estado = 1
  AND t.tie_importar_venta = 1
  AND t.tie_codigo_neg IN (1, 2, 3)
  AND TRY_CONVERT(INT, t.tie_codigo_aloha) IS NOT NULL
  AND (@negocio_filtro IS NULL OR t.tie_codigo_neg = @negocio_filtro);

-- Mismas tablas que usan vta.rvd_DocumentosGT / vta.rvd_DocumentosGndsale / vta.rvd_GuardarDocumentos.
DROP TABLE IF EXISTS #stg_gt;
DROP TABLE IF EXISTS #stg_gnd;
DROP TABLE IF EXISTS #documentos;
CREATE TABLE #stg_gt (
    DocTypeId NVARCHAR(5), TermId INT, DateOfBusiness DATETIME, CheckNumber INT,
    TaxableAmount DECIMAL(18, 4), TotalTax DECIMAL(18, 4), TotalTxn DECIMAL(18, 4),
    PropinaCheck DECIMAL(18, 4), SysDate DATETIME, GUID NVARCHAR(50)
);
CREATE TABLE #stg_gnd (
    CheckNumber INT, Tipo INT, TypeId INT, TypeId2 INT, Amount DECIMAL(18, 4), CloseHour INT, CloseMin INT
);
CREATE TABLE #documentos (
    categoria VARCHAR(20) NOT NULL, es_reembolso INT NOT NULL, cuenta_venta INT NOT NULL,
    venta_sin_iva DECIMAL(18, 6) NOT NULL, iva DECIMAL(18, 6) NOT NULL, venta_con_iva DECIMAL(18, 6) NOT NULL,
    propina DECIMAL(18, 6) NOT NULL, reembolso_sin_iva DECIMAL(18, 6) NOT NULL, momento DATETIME NULL
);

-- ─── B.3 Grabar cada tienda ─────────────────────────────────────────────────────────
-- Tienda sin datos en el CSV: se quita lo que hubiera en el día destino (no comparar contra el miércoles).
DECLARE @inicio  DATETIME2(0) = SYSDATETIME();
DECLARE @desfase INT = DATEDIFF(DAY, @fecha_origen, @fecha_destino);
DECLARE @origen_txt NVARCHAR(10) = CONVERT(NVARCHAR(10), @fecha_origen, 23);
DECLARE @i INT = 1, @max INT = (SELECT MAX(id) FROM #tiendas);
DECLARE @tienda INT, @neg INT, @hora_dallas BIT, @leidos INT, @t0 DATETIME2,
        @estado VARCHAR(20), @mensaje NVARCHAR(4000);

WHILE @i <= @max
BEGIN
    SELECT @tienda = tienda, @neg = codigo_neg FROM #tiendas WHERE id = @i;
    SELECT @t0 = SYSDATETIME(), @leidos = 0;

    BEGIN TRY
        TRUNCATE TABLE #stg_gt;
        TRUNCATE TABLE #stg_gnd;
        TRUNCATE TABLE #documentos;

        IF @neg = 1
        BEGIN
            INSERT INTO #stg_gt
            SELECT tipo, caja, @fecha_origen, check_number, taxable, iva, total, propina_check, sysdate, NULL
            FROM #aloha_inv
            WHERE tienda = @tienda;
            EXEC vta.rvd_DocumentosGT;
        END
        ELSE
        BEGIN
            -- Un check del CSV = su línea de venta (52) y la de su caja (44), como las lee vta.rvd_DocumentosGndsale.
            INSERT INTO #stg_gnd (CheckNumber, Tipo, TypeId, TypeId2, Amount, CloseHour, CloseMin)
            SELECT g.check_number, v.tipo, 0, CASE WHEN v.tipo = 44 THEN g.caja END,
                   CASE WHEN v.tipo = 52 THEN g.venta ELSE 0 END, g.hora_cierre, g.minuto_cierre
            FROM #aloha_gnd g
            CROSS JOIN (VALUES (52), (44)) v (tipo)
            WHERE g.tienda = @tienda
              AND (v.tipo = 52 OR g.caja IS NOT NULL);
            SET @hora_dallas = CASE WHEN @neg = 3 THEN 1 ELSE 0 END;
            EXEC vta.rvd_DocumentosGndsale @fecha = @fecha_origen, @hora_dallas = @hora_dallas;
        END;

        -- Misma hora del día, en la fecha destino.
        UPDATE #documentos SET momento = DATEADD(DAY, @desfase, momento) WHERE momento IS NOT NULL;

        SET @leidos = (SELECT COUNT(*) FROM #documentos);

        IF @leidos = 0
        BEGIN
            DELETE FROM vta.rvt_rvd_resumen_venta_diaria
            WHERE rvd_fecha = @fecha_destino AND rvd_codigo_tie = @tienda;
            SELECT @estado = 'SIN_DATOS', @mensaje = N'Histórico ALOHA ' + @origen_txt + N': sin datos (día destino vacío)';
        END
        ELSE
        BEGIN
            EXEC vta.rvd_GuardarDocumentos @fecha = @fecha_destino, @tienda = @tienda, @reconstruir = 1;
            SELECT @estado = 'OK', @mensaje = N'Histórico ALOHA ' + @origen_txt;
        END;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SELECT @estado = 'ERROR', @mensaje = N'Histórico ALOHA ' + @origen_txt + N': ' + ERROR_MESSAGE();
    END CATCH;

    -- El reintento automático solo mira los últimos 7 días: no toca esta fecha.
    INSERT INTO vta.rvt_lik_log_importacion_kio (
        lik_ejecucion, lik_fecha_negocio, lik_codigo_tie, lik_estado,
        lik_documentos_leidos, lik_segundos, lik_mensaje)
    VALUES (
        @inicio, @fecha_destino, @tienda, @estado,
        @leidos, DATEDIFF(MILLISECOND, @t0, SYSDATETIME()) / 1000.0, @mensaje);

    SET @i += 1;
END;

-- ─── B.4 Resultado ──────────────────────────────────────────────────────────────────
-- B.4.1 Por tienda: lo grabado (sin IVA y sin propina, moneda local) vs la venta TYPE 52 de GNDSALE, que
--       ya viene sin IVA ni propina. SV/USA deben ser iguales; GT difiere por centavos de redondeo
--       (validado con los CSV: total GT Q41 de diferencia, casi todo en 195 y 112).
SELECT t.codigo_neg AS negocio, t.tienda, l.lik_estado AS estado, l.lik_documentos_leidos AS documentos,
       a.gndsale_sin_iva, r.grabado_sin_iva, r.grabado_sin_iva - a.gndsale_sin_iva AS diferencia,
       r.bloques, r.primer_bloque, r.ultimo_bloque, l.lik_mensaje AS mensaje
FROM #tiendas t
JOIN vta.rvt_lik_log_importacion_kio l
  ON l.lik_codigo_tie = t.tienda AND l.lik_ejecucion = @inicio AND l.lik_fecha_negocio = @fecha_destino
OUTER APPLY (
    SELECT SUM(g.venta) AS gndsale_sin_iva FROM #aloha_gnd g WHERE g.tienda = t.tienda
) a
OUTER APPLY (
    SELECT COUNT(DISTINCT x.rvd_bloque) AS bloques, MIN(x.rvd_bloque) AS primer_bloque, MAX(x.rvd_bloque) AS ultimo_bloque,
           SUM(CASE WHEN x.rvd_ultimo_bloque = 1 THEN x.rvd_venta_sin_iva ELSE 0 END) AS grabado_sin_iva
    FROM vta.rvt_rvd_resumen_venta_diaria x
    WHERE x.rvd_fecha = @fecha_destino AND x.rvd_codigo_tie = t.tienda
) r
ORDER BY CASE l.lik_estado WHEN 'ERROR' THEN 0 WHEN 'SIN_DATOS' THEN 1 ELSE 2 END, t.codigo_neg, t.tienda;

-- B.4.2 Tiendas del CSV que no están en el ranking (no se cargaron). Informativo.
SELECT DISTINCT x.tienda
FROM (SELECT tienda FROM #aloha_inv UNION SELECT tienda FROM #aloha_gnd) x
WHERE x.tienda NOT IN (SELECT tienda FROM #tiendas)
ORDER BY x.tienda;

-- B.4.3 Integridad: un solo último bloque por tienda en el día destino. 0 filas.
SELECT rvd_codigo_tie
FROM vta.rvt_rvd_resumen_venta_diaria
WHERE rvd_fecha = @fecha_destino AND rvd_ultimo_bloque = 1
GROUP BY rvd_codigo_tie
HAVING COUNT(DISTINCT rvd_bloque) <> 1;
GO

-- ─── B.5 Fecha especial ─────────────────────────────────────────────────────────────
-- Para que la pantalla ofrezca el 26/11 debe estar activa en vta.rvt_fes_fecha_especial para cada negocio.
SELECT * FROM vta.rvt_fes_fecha_especial WHERE fes_mes = 11 AND fes_dia = 26;
